"use client";

import "../../styles/teum-base.css";
import "../../styles/components/spinner.css";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type SpinnerProps = ComponentPropsWithRef<"span"> & {
  size?: "small" | "medium" | "large";
  label?: string;
};

export function Spinner({ className, size = "medium", label = "Loading", ...props }: SpinnerProps) {
  return <span className={cn("teum-loading-spinner", `teum-loading-spinner--${size}`, className)} role="status" aria-label={label} {...props}><span aria-hidden="true" /></span>;
}

/* Generated from src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-loading-spinner { display: inline-grid; place-items: center; color: currentColor; }

.teum-loading-spinner > span { width: 100%; height: 100%; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: teum-spin 620ms linear infinite; }

@media (prefers-reduced-motion: reduce) {
.teum-loading-spinner > span { animation-duration: 2.4s; }
}

@keyframes teum-spin { to { transform: rotate(360deg); } }
}
